void draw_logo(void) {
    for (int row = 0; row < 200; row++) {
        for (int col = 0; col < 320; col++) {
            int index = row * 320 + col;
            int r = chOS_logo[index * 3];
            int g = chOS_logo[index * 3 + 1];
            int b = chOS_logo[index * 3 + 2];
            screen::putpixel(col, row, r, g, b);
        }
    }
}

struct multiboot_mmap_entry
{
  uint32_t size;
  uint32_t addr_low;
  uint32_t addr_high;
  uint32_t len_low;
  uint32_t len_high;
#define MULTIBOOT_MEMORY_AVAILABLE              1
#define MULTIBOOT_MEMORY_RESERVED               2
#define MULTIBOOT_MEMORY_ACPI_RECLAIMABLE       3
#define MULTIBOOT_MEMORY_NVS                    4
#define MULTIBOOT_MEMORY_BADRAM                 5
  uint32_t type;
} __attribute__((packed));

struct multiboot_info
{
  /* Multiboot info version number */
  uint32_t flags;

  /* Available memory from BIOS */
  uint32_t mem_lower;
  uint32_t mem_upper;

  /* "root" partition */
  uint32_t boot_device;

  /* Kernel command line */
  uint32_t cmdline;

  /* Boot-Module list */
  uint32_t mods_count;
  uint32_t mods_addr;


  /* flags 4,5 */
  uint32_t dummy1;
  uint32_t dummy2;
  uint32_t dummy3;
  uint32_t dummy4;
//   union
//   {
//     multiboot_aout_symbol_table_t aout_sym;
//     multiboot_elf_section_header_table_t elf_sec;
//   } u;

  /* Memory Mapping buffer */
  uint32_t mmap_length;
  uint32_t mmap_addr;

  /* Drive Info buffer */
  uint32_t drives_length;
  uint32_t drives_addr;

  /* ROM configuration table */
  uint32_t config_table;

  /* Boot Loader Name */
  uint32_t boot_loader_name;

  /* APM table */
  uint32_t apm_table;

  /* Video */
  uint32_t vbe_control_info;
  uint32_t vbe_mode_info;
  uint16_t vbe_mode;
  uint16_t vbe_interface_seg;
  uint16_t vbe_interface_off;
  uint16_t vbe_interface_len;

  uint32_t framebuffer_addr_low;
  uint32_t framebuffer_addr_high;
  uint32_t framebuffer_pitch;
  uint32_t framebuffer_width;
  uint32_t framebuffer_height;
  uint8_t framebuffer_bpp;
#define MULTIBOOT_FRAMEBUFFER_TYPE_INDEXED 0
#define MULTIBOOT_FRAMEBUFFER_TYPE_RGB     1
#define MULTIBOOT_FRAMEBUFFER_TYPE_EGA_TEXT     2
  uint8_t framebuffer_type;
  union
  {
    struct
    {
      uint32_t framebuffer_palette_addr;
      uint16_t framebuffer_palette_num_colors;
    };
    struct
    {
      uint8_t framebuffer_red_field_position;
      uint8_t framebuffer_red_mask_size;
      uint8_t framebuffer_green_field_position;
      uint8_t framebuffer_green_mask_size;
      uint8_t framebuffer_blue_field_position;
      uint8_t framebuffer_blue_mask_size;
    };
  };
};

extern uint32_t multiboot_info_ptr;
extern uint32_t multiboot_magic;
extern uint32_t _linker_end;

extern "C"
void kernel_main(void) 
{
    /* Initialize */
	setup_gdt32();

    // screen::init();
    terminal::initialize();
    
    load_idt();
    (void) welcomelogo;
    terminal::writestring(welcomelogo);

    char buf[100];
    struct multiboot_info info = *(struct multiboot_info *)multiboot_info_ptr;

    terminal::writestring(terminal::itoa(multiboot_magic, buf, 16));
    terminal::writestring("\n");
    terminal::writestring(terminal::itoa(info.flags, buf, 2));
    terminal::writestring("\n");

    void* mem_start = (void*)&_linker_end;
    void* mem_end = 0;

    struct multiboot_mmap_entry *mmap;
    for (mmap = (struct multiboot_mmap_entry *) info.mmap_addr;
        (unsigned long) mmap < info.mmap_addr + info.mmap_length;
        mmap = (struct multiboot_mmap_entry *) ((unsigned long) mmap
                                + mmap->size + sizeof (mmap->size)))
        {   
            if (mmap->type == 0x1 && mmap->addr_low == 0x100000) {
                mem_end = (void*) (mmap->len_low + 0x100000);
            }
        }

    terminal::writestring(terminal::itoa((int)mem_start, buf, 16));
    terminal::writestring("\n");

    terminal::writestring(terminal::itoa((int)mem_end, buf, 16));
    terminal::writestring("\n");


    // draw_logo();
    // world::init(screen::width(), screen::height());
    // world::run();

    for(;;) {}  // hang for now
}